MATCH (c:Company)
WHERE EXISTS {
  (c)-[:foundedBy]->(:Person {name: 'Gunnar Hordvik'})
} OR EXISTS {
  (c)-[:subsidiaryOf]->(:Company {name: 'EMI'})
}
OPTIONAL MATCH (c)-[:foundedBy]->(founder:Person)
OPTIONAL MATCH (c)-[:subsidiaryOf]->(parent:Company)
RETURN c.name AS company_name,
       collect(DISTINCT founder.name) AS founders,
       collect(DISTINCT parent.name) AS parent_companies

